# change: alf_loop_guard_v4 (p-alfworld-2-2)
def applies(view):
    return True


def alf_after_step(event, state):
    st = state if isinstance(state, dict) else {}
    counts = dict(st.get("counts", {}))
    a = event.get("action") or ""
    counts[a] = counts.get(a, 0) + 1
    o = (event.get("observation") or "").strip()
    if o.startswith("Nothing happens"):
        ns = st.get("nothing_streak", 0) + 1
    else:
        ns = 0
    return {"step": st.get("step", -1) + 1, "counts": counts,
            "nothing_streak": ns}


def alf_before_step(view, state):
    if not isinstance(state, dict):
        return {"fields": {}, "discourage": []}
    warn = []
    disc = []
    n = state.get("step", -1) + 1
    for a, c in sorted(state.get("counts", {}).items()):
        nav = isinstance(a, str) and a.startswith("go to ")
        if c >= 5 and a in ("look", "inventory"):
            warn.append(("'%s' has been used %d times so far this episode."
                         % (a, c))[:200])
        elif c >= 3 and not nav:
            warn.append(("Action '%s' has been executed %d times so far this "
                         "episode." % (a[:80], c))[:200])
        elif c >= 4 and nav:
            warn.append(("Action '%s' has been executed %d times so far this "
                         "episode." % (a[:80], c))[:200])
        if c >= 4:
            disc.append(a)
    ns = state.get("nothing_streak", 0)
    if ns >= 2:
        warn.append("The last %d actions in a row each returned 'Nothing "
                    "happens'." % ns)
    if n >= 20 and n % 5 == 0:
        warn.append("Steps used so far: %d of 50." % n)
    if warn:
        return {"fields": {"warnings": warn[:4]}, "discourage": disc[:5]}
    return {"fields": {}, "discourage": []}
